"""Local replay-only product demo for M8."""

from pathlib import Path

from fastapi import FastAPI, HTTPException, Query
from fastapi.responses import HTMLResponse

from gauntlet.demo.m8 import load_m8_replay


def create_m8_demo_app(repository_root: Path) -> FastAPI:
    root = repository_root.resolve(strict=True)
    app = FastAPI(title="Gauntlet Product Demo")

    @app.get("/", response_class=HTMLResponse)
    async def index() -> str:
        return _HTML

    @app.get("/api/replay")
    async def replay(
        threshold_minor: int = Query(default=5_000, ge=0, le=1_000_000),
    ) -> dict:
        try:
            return load_m8_replay(root, threshold_minor).model_dump(mode="json")
        except Exception as exc:
            raise HTTPException(422, str(exc)) from exc

    @app.get("/api/health")
    async def health() -> dict[str, str]:
        return {"status": "ok", "mode": "Verified Replay"}

    return app


